import numpy as np
from scipy import stats
from scipy.optimize import brentq

def r_binWidth(n, p, conf_level=0.95, alternative="two.sided", method="CP"):
    # Input validation
    if n < 3:
        raise ValueError(" nmax must be at least 3 ")
    if not isinstance(n, (int, np.integer)):
        if isinstance(n, (list, np.ndarray)):
            if len(n) < 1 or len(n) > 2:
                raise ValueError(" n must be either a single integer or a vector of two integers")
            n = int(n[0])
        else:
            n = int(n)

    if conf_level < 0 or conf_level > 1:
        raise ValueError(" conf.level must be a value between 0 and 1 ")
    if p < 0 or p > 1:
        raise ValueError(" p.hyp must be a value between 0 and 1")

    if method not in ["CP", "Blaker", "AC", "Score", "Wald", "SOC"]:
        raise ValueError(f"method must be one of CP, Blaker, AC, Score, Wald, SOC")
    if alternative not in ["two.sided", "less", "greater"]:
        raise ValueError("alternative must be one of two.sided, less, greater")

    # Helper functions for confidence intervals
    def binWald(y, n, conf_level, alternative):
        p_hat = y / n if n > 0 else 0
        if alternative == "two.sided":
            z = stats.norm.ppf(1 - (1 - conf_level) / 2)
        else:
            z = stats.norm.ppf(1 - (1 - conf_level))
        se = np.sqrt(p_hat * (1 - p_hat) / n) if n > 0 else 0
        lower = p_hat - z * se
        upper = p_hat + z * se
        lower = np.clip(lower, 0, 1)
        upper = np.clip(upper, 0, 1)
        return [lower, upper]

    def binWilson(y, n, conf_level, alternative):
        p_hat = y / n if n > 0 else 0
        if alternative == "two.sided":
            z = stats.norm.ppf(1 - (1 - conf_level) / 2)
        else:
            z = stats.norm.ppf(1 - (1 - conf_level))

        denom = 1 + z**2 / n
        center = (p_hat + z**2 / (2*n)) / denom
        margin = z * np.sqrt(p_hat * (1 - p_hat) / n + z**2 / (4*n**2)) / denom
        lower = center - margin
        upper = center + margin
        lower = np.clip(lower, 0, 1)
        upper = np.clip(upper, 0, 1)
        return [lower, upper]

    def binAC(y, n, conf_level, alternative):
        if alternative == "two.sided":
            z = stats.norm.ppf(1 - (1 - conf_level) / 2)
        else:
            z = stats.norm.ppf(1 - (1 - conf_level))

        lower = (y + z**2 / 2 - z * np.sqrt(y + z**2 / 4)) / (n + z**2)
        upper = (y + z**2 / 2 + z * np.sqrt(y + z**2 / 4)) / (n + z**2)
        lower = np.clip(lower, 0, 1)
        upper = np.clip(upper, 0, 1)
        return [lower, upper]

    def binSOC(y, n, conf_level, alternative):
        if alternative == "two.sided":
            z = stats.norm.ppf(1 - (1 - conf_level) / 2)
        else:
            z = stats.norm.ppf(1 - (1 - conf_level))

        lower = (y + z**2 / 2 - z * np.sqrt(y + z**2 / 4)) / (n + z**2)
        upper = (y + z**2 / 2 + z * np.sqrt(y + z**2 / 4)) / (n + z**2)
        lower = np.clip(lower, 0, 1)
        upper = np.clip(upper, 0, 1)
        return [lower, upper]

    def binCP(y, n, conf_level, alternative):
        alpha = 1 - conf_level
        if alternative == "two.sided":
            alpha_lower = alpha / 2
            alpha_upper = alpha / 2
        elif alternative == "less":
            alpha_lower = 0
            alpha_upper = alpha
        else:  # greater
            alpha_lower = alpha
            alpha_upper = 0

        # Lower bound: P(X >= y | p) = alpha_lower, or equivalently P(X < y | p) = 1 - alpha_lower
        if y == 0:
            lower = 0.0
        else:
            try:
                # Solve: P(X < y | p) = 1 - alpha_lower, i.e., P(X <= y-1 | p) = 1 - alpha_lower
                lower = brentq(lambda pp: stats.binom.cdf(y - 1, n, pp) - (1 - alpha_lower), 1e-10, 1 - 1e-10)
            except:
                lower = 0.0

        # Upper bound: P(X <= y | p) = alpha_upper, or equivalently P(X > y | p) = 1 - alpha_upper
        if y == n:
            upper = 1.0
        else:
            try:
                # Solve: P(X > y | p) = 1 - alpha_upper, i.e., P(X >= y+1 | p) = 1 - alpha_upper
                upper = brentq(lambda pp: stats.binom.sf(y, n, pp) - (1 - alpha_upper), 1e-10, 1 - 1e-10)
            except:
                upper = 1.0

        return [lower, upper]

    def binBlaker(y, n, conf_level):
        alpha = 1 - conf_level

        # Blaker's method: use tail probability approach
        if y == 0:
            lower = 0.0
        else:
            def f_lower(pp):
                # For lower bound, find p such that the acceptance region includes y
                # Using the inverted two-tailed test
                tail_prob = min(stats.binom.cdf(y, n, pp), stats.binom.sf(y - 1, n, pp))
                return tail_prob - alpha / 2
            try:
                lower = brentq(f_lower, 1e-10, 1 - 1e-10)
            except:
                lower = 0.0

        if y == n:
            upper = 1.0
        else:
            def f_upper(pp):
                tail_prob = min(stats.binom.cdf(y, n, pp), stats.binom.sf(y - 1, n, pp))
                return tail_prob - alpha / 2
            try:
                upper = brentq(f_upper, 1e-10, 1 - 1e-10)
            except:
                upper = 1.0

        return [lower, upper]

    def L_Ind_bin(y, n, p_hyp, conf_level, alternative, method):
        if method == "Wald":
            int_ci = binWald(y, n, conf_level, alternative)
        elif method == "Score":
            int_ci = binWilson(y, n, conf_level, alternative)
        elif method == "AC":
            int_ci = binAC(y, n, conf_level, alternative)
        elif method == "SOC":
            int_ci = binSOC(y, n, conf_level, alternative)
        elif method == "CP":
            int_ci = binCP(y, n, conf_level, alternative)
        elif method == "Blaker":
            int_ci = binBlaker(y, n, conf_level)

        if alternative == "less":
            CIlength = int_ci[1] - p_hyp
        elif alternative == "greater":
            CIlength = p_hyp - int_ci[0]
        else:  # two.sided
            CIlength = int_ci[1] - int_ci[0]

        return CIlength

    def bin_prob(y, n, p_prob):
        return stats.binom.pmf(y, n, p_prob)

    yvec = np.arange(0, n + 1)
    Lvec = np.zeros(len(yvec))
    probvec = np.zeros(len(yvec))

    for i, y in enumerate(yvec):
        Lvec[i] = L_Ind_bin(y, n, p, conf_level, alternative, method)
        probvec[i] = bin_prob(y, n, p)

    expCILength = np.sum(Lvec * probvec)

    return {
        "expCIWidth": float(expCILength),
        "alternative": alternative,
        "p": float(p),
        "n": int(n)
    }
